import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';
void main()=>runApp(const App());class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp.router(title:'Veyra',theme:ThemeData(useMaterial3:true),routerConfig:r);}
final r=GoRouter(initialLocation:'/login',routes:[for(final x in ['/login','/home','/addresses','/options','/review','/offers','/confirmed','/live','/chat','/history','/profile'])GoRoute(path:x,builder:(c,s)=>Screen(x))]);
class Screen extends StatelessWidget{final String p;const Screen(this.p,{super.key});@override Widget build(BuildContext c){final data=<String,List<String>>{
'/login':['Connexion','Email','Mot de passe','Se connecter'],'/home':['Veyra','Planifier une réservation','Prochaines réservations','Historique'],'/addresses':['Trajet','Adresse de départ — autocomplete','Destination — autocomplete','Continuer'],'/options':['Date et options','Minimum 2 h à l’avance','Standard • Comfort • Van','Cash • En ligne'],'/review':['Récapitulatif','Trajet programmé','Publier la demande'],'/offers':['Offres reçues','Comparez prix, véhicule et note','Choisir une offre'],'/confirmed':['Réservation confirmée','PIN 4 chiffres disponible à H-1','Chat Veyra','Appeler le chauffeur'],'/live':['Course','Carte temps réel','Position chauffeur','Statut de la course'],'/chat':['Chat Veyra','Conversation disponible après confirmation','Votre message'],'/history':['Historique','À venir • Terminées • Annulées'],'/profile':['Profil','Compte • Notifications • Confidentialité • Déconnexion']};final a=data[p]!;
return Scaffold(appBar:AppBar(title:Text(a.first)),body:SafeArea(child:ListView(padding:const EdgeInsets.all(20),children:[for(final t in a.skip(1))Card(child:ListTile(title:Text(t))),const SizedBox(height:12),if(p=='/login')FilledButton(onPressed:()=>c.go('/home'),child:const Text('Se connecter')),if(p=='/home')FilledButton(onPressed:()=>c.go('/addresses'),child:const Text('Planifier')),if(p=='/addresses')FilledButton(onPressed:()=>c.go('/options'),child:const Text('Continuer')),if(p=='/options')FilledButton(onPressed:()=>c.go('/review'),child:const Text('Continuer')),if(p=='/review')FilledButton(onPressed:()=>c.go('/offers'),child:const Text('Publier')),if(p=='/offers')FilledButton(onPressed:()=>c.go('/confirmed'),child:const Text('Choisir')),if(p=='/confirmed')FilledButton(onPressed:()=>c.go('/live'),child:const Text('Suivi jour J'))])));}}
